package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Rect;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.TextView;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.Test;import java.io.File;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Native settings and fake explicit arm only. No sensor, charging change or Service. */
public final class ArmedWaitFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);volatile Activity current;
    interface Check {boolean ready()throws Exception;}
    void await(String operation,Check check)throws Exception{long deadline=SystemClock.elapsedRealtime()+12000;while(!check.ready()){if(SystemClock.elapsedRealtime()>deadline)throw new AssertionError("Armed wait fixture did not reach "+operation);Thread.sleep(30);}}
    View root(){for(View view:WindowInspector.getGlobalWindowViews())if(view.hasWindowFocus()&&view.isAttachedToWindow()&&view.getContext().getPackageName().equals(c.getPackageName()))return view;return null;}
    View exact(View view,String label,boolean description){if(view==null)return null;if(description?label.contentEquals(view.getContentDescription()==null?"":view.getContentDescription()):view instanceof TextView&&label.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=exact(group.getChildAt(n),label,description);if(found!=null)return found;}return null;}
    View find(View view,String label){View result=exact(view,label,true);return result==null?exact(view,label,false):result;}
    Rect target(String label,boolean clickable){Rect[] result={null};i.runOnMainSync(()->{View view=find(root(),label);if(clickable)while(view!=null&&!view.isClickable())view=view.getParent() instanceof View?(View)view.getParent():null;if(view==null||!view.isEnabled())return;Rect visible=new Rect();if(!view.getGlobalVisibleRect(visible)||visible.width()!=view.getWidth()||visible.height()!=view.getHeight()){view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),false);return;}if(clickable&&(visible.height()<Design.dp(c,48)||visible.width()<Design.dp(c,48)))return;int[] screen=new int[2];view.getLocationOnScreen(screen);result[0]=new Rect(screen[0],screen[1],screen[0]+view.getWidth(),screen[1]+view.getHeight());});return result[0];}
    void frame()throws Exception{CountDownLatch commit=new CountDownLatch(1);i.runOnMainSync(()->{View owner=root();assertNotNull("Focused app window",owner);owner.getViewTreeObserver().registerFrameCommitCallback(commit::countDown);owner.invalidate();});assertTrue("Committed app frame",commit.await(5,TimeUnit.SECONDS));}
    UiObject2 object(String description)throws Exception{await("visible "+description,()->target(description,false)!=null);frame();UiObject2 view=d.wait(Until.findObject(By.desc(description)),5000);assertNotNull(description,view);return view;}
    void click(String label)throws Exception{await("clickable "+label,()->target(label,true)!=null);frame();Rect bounds=target(label,true);assertNotNull(label,bounds);assertTrue(d.click(bounds.centerX(),bounds.centerY()));}
    boolean ime(){boolean[] visible={false};i.runOnMainSync(()->{View owner=root();WindowInsets insets=owner==null?null:owner.getRootWindowInsets();visible[0]=insets!=null&&insets.isVisible(WindowInsets.Type.ime());});return visible[0];}
    void finishInput()throws Exception{if(ime()){assertTrue(d.pressBack());await("closed keyboard",()->!ime());}}
    void shown(String text){assertTrue(text,d.wait(Until.hasObject(By.text(text)),6000));}
    void recreate(String text)throws Exception{Activity before=current;Instrumentation.ActivityMonitor monitor=i.addMonitor(current.getClass().getName(),null,false);try{i.runOnMainSync(current::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}await("recreated focused activity",()->current!=before&&current.hasWindowFocus());shown(text);}
    void capture(String name)throws Exception{i.waitForIdleSync();frame();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"armed-wait-"+name+".png")));}
    void launch()throws Exception{Activity value=i.startActivitySync(new Intent(c,AutomaticTrackingActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));current=value;await("focused settings",value::hasWindowFocus);shown("Automatic tracking");}
    @Test public void explicitConditionsSaveRecreateReopenAndFreezeOnlyFakeArm()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());String name="armed-wait-flow-"+UUID.randomUUID();SharedPreferences preferences=c.getSharedPreferences(name,0);Map<String,?> personal=new HashMap<>(Prefs.of(c).getAll());AutomaticTrackingActivity.Port old=AutomaticTrackingActivity.port;List<Activity> owned=new CopyOnWriteArrayList<>();List<ArmedWaitConditions> armed=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callback=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue(a instanceof AutomaticTrackingActivity);owned.add(a);}public void onActivityResumed(Activity a){current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callback);
        try{assertFalse(TrackingService.running);assertFalse(AlarmService.active);preferences.edit().putString("automaticMode","BEDTIME").commit();AutomaticTrackingActivity.port=new AutomaticTrackingActivity.Port(){public SharedPreferences preferences(Activity a){return preferences;}public long schedule(Activity a,AutomaticSleep.Mode mode){return System.currentTimeMillis()+1800000;}public boolean movementAvailable(Activity a){return true;}public boolean notificationsAllowed(Activity a){return true;}public boolean microphoneAllowed(Activity a){return true;}public void arm(Activity a,AutomaticSleep.Mode mode,long at,boolean sounds,boolean clips){throw new AssertionError("Conditions must use the typed arm boundary");}public void arm(Activity a,AutomaticSleep.Mode mode,long at,boolean sounds,boolean clips,ArmedWaitConditions conditions){assertEquals(AutomaticSleep.Mode.BEDTIME,mode);assertFalse(sounds);assertFalse(clips);armed.add(conditions);}};launch();assertFalse(object("Wait for charging").isChecked());assertFalse(object("Wait for screen off").isChecked());click("Wait for charging");click("Wait for screen off");await("both wait conditions selected",()->{boolean[] selected={false};i.runOnMainSync(()->selected[0]=((android.widget.CompoundButton)find(root(),"Wait for charging")).isChecked()&&((android.widget.CompoundButton)find(root(),"Wait for screen off")).isChecked());return selected[0];});assertTrue(object("Wait for charging").isChecked());assertTrue(object("Wait for screen off").isChecked());capture("settings");recreate("Automatic tracking");assertTrue(object("Wait for charging").isChecked());assertTrue(object("Wait for screen off").isChecked());capture("recreated");assertFalse("Draft recreation must not save settings",preferences.getBoolean(ArmedWaitSettings.CHARGING,false));Activity editor=current;click("Save settings");await("saved settings destroyed",editor::isDestroyed);assertTrue(ArmedWaitSettings.read(preferences).charging);assertTrue(ArmedWaitSettings.read(preferences).screenOff);assertEquals(0,armed.size());launch();assertTrue(object("Wait for charging").isChecked());assertTrue(object("Wait for screen off").isChecked());capture("reopened");click("Arm tonight");await("one exact fake arm",()->armed.size()==1);ArmedWaitConditions frozen=armed.get(0);assertTrue(frozen.charging);assertTrue(frozen.screenOff);ArmedWaitSettings.put(preferences.edit(),ArmedWaitConditions.NONE).commit();assertTrue(frozen.charging);assertTrue(frozen.screenOff);assertFalse(ArmedWaitSettings.read(preferences).charging);assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertEquals(personal,Prefs.of(c).getAll());
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());d.takeScreenshot(new File(folder,"armed-wait-failure.png"));d.dumpWindowHierarchy(new File(folder,"armed-wait-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});await("owned settings destroyed",()->owned.stream().allMatch(Activity::isDestroyed));app.unregisterActivityLifecycleCallbacks(callback);AutomaticTrackingActivity.port=old;c.deleteSharedPreferences(name);assertEquals(personal,Prefs.of(c).getAll());}}
}
